/**
 * Higher-Order Component that conditionally wraps a component with a provider
 * if the context is not already available in the component tree.
 *
 * @param TargetComponent - The component to potentially wrap
 * @param contextToCheck - The React Context to check for existence
 * @param WrapperProvider - The Provider component to wrap with if context doesn't exist
 * @returns A new component that conditionally wraps TargetComponent
 *
 * @example
 * ```typescript
 * // RecordProvider will be wrapped with NotificationsProvider only if
 * // NotificationsContext is not already in the tree
 * const RecordProviderWithNotifications = withContextIfNotWrapped(
 * RecordProvider,
 * NotificationsContext,
 * NotificationsProvider
 * );
 *
 * // Usage 1: NotificationsProvider not in tree - will wrap
 * <RecordProviderWithNotifications table="incident" sysId="123">
 * <MyComponent />
 * </RecordProviderWithNotifications>
 *
 * // Usage 2: NotificationsProvider already in tree - won't wrap
 * <NotificationsProvider>
 * <RecordProviderWithNotifications table="incident" sysId="123">
 * <MyComponent />
 * </RecordProviderWithNotifications>
 * </NotificationsProvider>
 * ```
 */
function withContextIfNotWrapped(TargetComponent, contextToCheck, WrapperProvider) {
 const WrappedComponent = (props) => {
 const contextValue = React.useContext(contextToCheck);
 const hasContext = contextValue !== null && contextValue !== undefined;
 if (hasContext) {
 // Context already exists in tree, render target without wrapper
 return React.createElement(TargetComponent, { ...props });
 }
 // Context doesn't exist, wrap with provider
 return (React.createElement(WrapperProvider, null,
 React.createElement(TargetComponent, { ...props })));
 };
 // Preserve display name for better debugging
 const targetName = TargetComponent.displayName || TargetComponent.name || 'Component';
 const wrapperName = WrapperProvider.displayName || WrapperProvider.name || 'Provider';
 WrappedComponent.displayName = `withContextIfNotWrapped(${targetName}, ${wrapperName})`;
 return WrappedComponent;
}

export { withContextIfNotWrapped };
