","import { useEffect } from 'react';
import { attachServiceNowEvent } from './events.js';

/**
 * Helper hook to attach ServiceNow event listeners to an element
 */
const useServiceNowEvent = (elementRef, eventName, handler) => {
 useEffect(() => {
 if (!elementRef.current || !handler)
 return;
 const cleanup = attachServiceNowEvent(elementRef.current, eventName, handler);
 return cleanup;
 }, [elementRef, eventName, handler]);
};

export { useServiceNowEvent };
//# sourceMappingURL=useServiceNowEvents.js.map
","import { useEffect } from 'react';

const setProperties = (ref, properties) => {
 return useEffect(() => {
 if (!ref.current)
 return;
 Object.keys(properties).forEach(key => {
 ref.current[key] = properties[key];
 });
 }, [ref, ...Object.values(properties)]);
};

export { setProperties };
//# sourceMappingURL=setProperties.js.map
","import React, { useRef } from 'react';
import '@servicenow/now-record-list-connected' assert { external: 'uxasset' };
import { useServiceNowEvent } from './utils/useServiceNowEvents.js';
import { setProperties } from './utils/setProperties.js';
import { ServiceNowEvents } from './utils/events.js';

const NowRecordListConnected = props => {
 const { table, listTitle, limit, view, columns, hideHeader, hideQuickEdit, hideInlineEditing, hideRowSelector, onNewActionClicked, onRowClicked, onSelectedRecordCountUpdated, onQueryUpdated, onDataFetchRequested, onDataFetchSucceeded, onRefreshRequested } = props;
 const elementRef = useRef(null);
 const onItemSelectedHandler = (e) => {
 /**
 * The legacy create-new action dispatches ITEM_SELECTED and not CREATE_NEW_RECORD
 * the contract for ITEM_SELECTED is very different
